import { DOCUMENT_KINDS, expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review with three pending extractions
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act: the reviewer approves all three extractions
  for (const kind of DOCUMENT_KINDS) {
    const response = await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, {
      data: { decision: "approve" },
    });
    await expectStatus(response, 200);
  }

  // Assert: the vendor is approved, and the approval is in the audit trail
  const stored = await expectStatus(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("approved");

  const trail = await expectStatus(await reviewer.get(`/api/vendors/${vendor.id}/audit`), 200);
  expect(trail.items.map((event: { action: string }) => event.action)).toContain("vendor.approved");
});
